84	static bool fetchQuotes() {
85	  WiFiClientSecure cli;
86	  cli.setInsecure();
87	  HTTPClient http;
88	  http.setTimeout(12000);
89	  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
90	  if (!http.begin(cli, API_URL)) return false;
91	  int code = http.GET();
92	  if (code != 200) {
93	    Serial.printf("[api] HTTP %d\n", code);
94	    http.end();
95	    return false;
96	  }
97	  String body = http.getString();
98	  http.end();
99	  JsonDocument doc;
100	  if (deserializeJson(doc, body)) return false;
101	  std::vector<Quote> fresh;
102	  auto parseOne = [&](JsonVariantConst o) {
103	    Quote q;
104	    q.idx = jstr(o, "idx");
105	    q.content = jstr(o, "content", "main_content");
106	    if (q.content.length() == 0) return;
107	    q.context = jstr(o, "context");
108	    q.date = jstr(o, "date", "effectiveDate");
109	    q.specific = jstr(o, "specific", "specificName");
110	    q.container = jstr(o, "container", "containerName");
111	    q.cat = jstr(o, "cat", "category");
112	    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
113	    for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
114	      String s = t.as<String>();
115	      if (!s.startsWith("#")) s = "#" + s;
116	      q.tags.push_back(s);
117	    }
118	    fresh.push_back(q);
119	  };
120	  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
121	  else parseOne(doc.as<JsonVariantConst>());
122	  if (fresh.empty()) return false;
123	  quotes = fresh;
124	  Serial.printf("[api] loaded %d quotes\n", (int)quotes.size());
125	  return true;
126	}
