128	// ------------------------------------------------------------------ utf-8
129	static std::u16string u8to16(const String& s) {
130	  std::u16string o;
131	  const uint8_t* p = (const uint8_t*)s.c_str();
132	  size_t n = s.length();
133	  for (size_t i = 0; i < n;) {
134	    uint8_t c = p[i];
135	    uint32_t cp;
136	    int len;
137	    if (c < 0x80) { cp = c; len = 1; }
138	    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
139	    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
140	    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
141	    else { i++; continue; }
142	    if (i + len > n) break;
143	    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
144	    i += len;
145	    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
146	  }
147	  return o;
148	}
