252	static void jqSend(const uint8_t* d, size_t n) {
253	  uint8_t sum = 0;
254	  for (size_t i = 0; i < n; i++) sum += d[i];
255	  Serial1.write(d, n);
256	  Serial1.write(sum);
257	}
258	static void jqPlay(uint8_t track) {
