301	static void drawHeader(const Quote& q, bool busy) {
302	  cv.h = HDR_H;
303	  cv.fill(C_BLACK);
304	  cv.rect(0, HDR_H - 1, SW, 1, C_RULE);
305	  const int base = 14;
306	  std::u16string date = u8to16(q.date.length() ? q.date : String("—"));
307	  int dateW = fSB10.adv * (int)date.size();
308	  int labelW = fRG10.adv * 5;
309	  int rightW = labelW + 4 + dateW;
310	  int rx = SW - 12 - rightW;
311	  cv.text(fRG10, rx, base, u"Date:", C_DIM);
312	  cv.text(fSB10, rx + labelW + 4, base, date, C_GHOST);
313	  int x = 12;
314	  if (busy) {
315	    cv.text(fRG10, x, base, u"// Receiving prescript...", C_GHOST);
316	  } else {
317	    std::u16string idx = u"#" + u8to16(q.idx);
318	    x += cv.text(fSB10, x, base, idx, C_GHOST) + 4;
319	    x += cv.text(fRG10, x, base, u"~", C_SEP) + 4;
320	    std::u16string title = u8to16(q.specific);
321	    int avail = rx - 8 - x;
322	    int maxCh = avail / fRG10.adv;
323	    if ((int)title.size() > maxCh && maxCh > 1) title = title.substr(0, maxCh - 1) + u"\u2026";
324	    cv.text(fRG10, x, base, title, C_TITLE, avail);
325	  }
326	  push(0, HDR_H);
327	}
