329	static void drawFooter(const Quote& q, int seed = 0) {
330	  cv.h = FTR_H;
331	  cv.fill(C_BLACK);
332	  cv.rect(0, 0, SW, 1, C_RULE);
333	  uint16_t accent = accentFor(q);
334	  const int base = 15;
335	  std::u16string cont = u8to16(q.container);
336	  int contMax = 150 / fSB10.adv;
337	  if ((int)cont.size() > contMax) cont = cont.substr(0, contMax - 1) + u"\u2026";
338	  int contW = fSB10.adv * (int)cont.size();
339	  int cx = SW - 12 - contW;
340	  cv.text(fSB10, cx, base, cont, accent);
341	  int x = 12;
342	  for (size_t i = 0; i < q.tags.size(); i++) {
343	    std::u16string t = u8to16(q.tags[i]);
344	    int w = fSB9.adv * (int)t.size() + 10 + 2;
345	    if (x + w > cx - 8) break;
346	    float hue = tagHue(q.tags[i], (int)i) + seed;
347	    uint16_t tcol = hsl565(hue, 0.85f, 0.72f), bg = hsl565(hue, 0.65f, 0.08f);
348	    uint16_t bd = mix565(C_BLACK, hsl565(hue, 0.70f, 0.40f), 115);
349	    const int y0 = 5, hh = 13;
350	    cv.rect(x, y0, w, hh, bd);
351	    cv.rect(x + 1, y0 + 1, w - 2, hh - 2, bg);
352	    cv.b[y0 * cv.w + x] = C_BLACK; cv.b[y0 * cv.w + x + w - 1] = C_BLACK;
353	    cv.b[(y0 + hh - 1) * cv.w + x] = C_BLACK; cv.b[(y0 + hh - 1) * cv.w + x + w - 1] = C_BLACK;
354	    cv.text(fSB9, x + 6, y0 + 10, t, tcol);
355	    x += w + 3;
356	  }
357	  push(SH - FTR_H, FTR_H);
358	}
