373	static void drawBodyLineFinal(const Line& ln, int y, bool ctx, uint16_t accent) {
374	  cv.h = 20;
375	  cv.fill(ctx ? C_BOXBG : C_BLACK);
376	  const VFont& fn = ctx ? fRG11 : fIT13;
377	  int base = (20 - (fn.ascent + fn.descent)) / 2 + fn.ascent;
378	  int cellW = fn.adv;
379	  int x0 = ctx ? 16 : 16;
380	  if (ctx) cv.rect(10, 0, 2, 20, C_DIM);
381	  const std::u16string& s = ln.t;
382	  std::vector<int> xs(s.size());
383	  int spaces = 0;
384	  for (char16_t c : s) if (c == ' ') spaces++;
385	  if (ln.just && spaces > 0) {
386	    int W = MAX_CHARS * cellW;
387	    int gap = W - (int)(s.size() - spaces) * cellW;
388	    int extra = gap - spaces * 0;
389	    int per = extra / spaces, rem = extra % spaces, x = x0, sp = 0;
390	    for (size_t i = 0; i < s.size(); i++) {
391	      xs[i] = x;
392	      if (s[i] == ' ') x += per + (sp++ < rem ? 1 : 0);
393	      else x += cellW;
394	    }
395	  } else {
396	    for (size_t i = 0; i < s.size(); i++) xs[i] = x0 + (int)i * cellW;
397	  }
398	  for (size_t i = 0; i < s.size(); i++) {
399	    char16_t c = s[i];
400	    if (c == ' ') continue;
401	    if (!ctx && (c == 0x201C || c == 0x201D || c == '.')) cv.drawChar(fBD13, xs[i], base, c, accent);
402	    else cv.drawChar(fn, xs[i], base, c, ctx ? C_GHOST : C_WHITE);
403	  }
404	  push(y, 20);
405	}
