407	static void renderPageFinal(const Page& pg, uint16_t accent) {
408	  clearBody();
409	  int y = bodyTop((int)pg.lines.size());
410	  for (size_t i = 0; i < pg.lines.size(); i++) drawBodyLineFinal(pg.lines[i], y + (int)i * LINE_PITCH, pg.ctx, accent);
411	}
