433	static void finishAnimation(bool playChime) {
434	  animating = false;
435	  renderPageFinal(pages[curPage], curAccent);
436	  drawHeader(quotes[curQuote], false);
437	  if (playChime) jqPlay(TRACK_COMPLETE);
438	  scheduleAutoPage();
439	}
440	
441	static void showPage(bool animate, bool sound) {
442	  const Quote& q = quotes[curQuote];
443	  curAccent = accentFor(q);
444	  autoPageAt = 0;
445	  Page& pg = pages[curPage];
446	  drawFooter(q);
447	  if (!animate || pg.ctx) {
448	    animating = false;
449	    drawHeader(q, false);
450	    renderPageFinal(pg, curAccent);
451	    if (sound) jqPlay(TRACK_COMPLETE);
452	    scheduleAutoPage();
453	    return;
454	  }
455	  drawHeader(q, true);
456	  clearBody();
457	  uint32_t total = max<uint32_t>(900, ENTROPY_MS * 35);
458	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
459	    const std::u16string& s = pg.lines[r].t;
460	    gridLen[r] = min<int>((int)s.size(), MAX_CHARS + 8);
461	    for (int c = 0; c < gridLen[r]; c++)
462	      grid[r][c] = {s[c], rndCipher(), (uint32_t)random(total), (uint32_t)random(40), false};
463	  }
464	  animating = true;
465	  animStart = millis();
466	  lastFrame = 0;
467	  if (sound) { jqPlay(TRACK_DRAW); nextChime = animStart + DRAW_TO_COMPLETE_MS; }
468	  else nextChime = 0xFFFFFFFF;
469	}
470	
471	static void loadQuote(int idx, bool animate, bool sound) {
472	  curQuote = idx;
473	  pages = buildPages(quotes[curQuote]);
474	  curPage = 0;
475	  g_missingGlyphs = 0;
476	  showPage(animate, sound);
477	  Serial.printf("[quote] #%s pages=%d missingGlyphs=%d heap=%u\n", quotes[curQuote].idx.c_str(),
478	                (int)pages.size(), g_missingGlyphs, ESP.getFreeHeap());
479	}
480	
481	static void rollQuote() {
482	  int n = (int)quotes.size(), i = curQuote;
483	  if (n > 1) while (i == curQuote) i = random(n);
484	  loadQuote(i, true, true);
485	}
486	
487	static void changePage() {
488	  if (animating) { finishAnimation(true); return; }
489	  curPage = (curPage + 1) % (int)pages.size();
490	  showPage(false, true);
491	}
492	
493	static void stepAnimation() {
494	  uint32_t now = millis();
495	  if (now >= nextChime) { jqPlay(TRACK_COMPLETE); nextChime = now + BETWEEN_COMPLETES_MS; }
496	  if (now - lastFrame < 33) return;
497	  lastFrame = now;
498	  uint32_t el = now - animStart;
499	  Page& pg = pages[curPage];
500	  bool all = true;
501	  int y = bodyTop((int)pg.lines.size());
502	  const int base = (20 - (fIT13.ascent + fIT13.descent)) / 2 + fIT13.ascent;
503	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
504	    cv.h = 20;
505	    cv.fill(C_BLACK);
506	    for (int c = 0; c < gridLen[r]; c++) {
507	      Cell& ce = grid[r][c];
508	      if (!ce.locked) {
509	        if (el >= ce.life) { ce.locked = true; ce.cur = ce.target; }
510	        else {
511	          all = false;
512	          if (el >= ce.nextScr) { ce.cur = rndCipher(); ce.nextScr = el + 35 + random(25); }
513	        }
514	      }
515	      int x = 16 + c * fIT13.adv;
516	      if (ce.locked) {
517	        if (ce.target == ' ') continue;
518	        if (ce.target == 0x201C || ce.target == 0x201D || ce.target == '.')
519	          cv.drawChar(fBD13, x, base, ce.target, curAccent);
520	        else cv.drawChar(fIT13, x, base, ce.target, C_WHITE);
521	      } else cv.drawChar(fIT13, x, base, ce.cur, C_WHITE);
522	    }
523	    push(y + r * LINE_PITCH, 20);
524	  }
525	  if (all) finishAnimation(true);
526	}
527	
528	// ------------------------------------------------------------------ boot UI
529	static void splash(const char* l1, const char* l2 = "") {
530	  cv.h = 24;
531	  tft.fillRect(0, 60, SW, 60, C_BLACK);
532	  std::u16string a = u8to16(l1), b = u8to16(l2);
533	  cv.fill(C_BLACK);
534	  cv.text(fSB10, (SW - (int)a.size() * fSB10.adv) / 2, 16, a, C_WHITE);
535	  push(66, 24);
536	  cv.fill(C_BLACK);
537	  cv.text(fRG10, (SW - (int)b.size() * fRG10.adv) / 2, 16, b, C_GHOST);
538	  push(92, 24);
539	}
