541	struct Btn {
542	  uint8_t pin; bool last = true; uint32_t t = 0;
543	  bool pressed() {
544	    bool v = digitalRead(pin);
545	    uint32_t now = millis();
546	    bool fire = (last && !v && now - t > 40);
547	    if (v != last) t = now;
548	    last = v;
549	    return fire;
550	  }
551	};
552	static Btn btnRoll = {PIN_BTN_ROLL}, btnScroll = {PIN_BTN_SCROLL};
553	static uint32_t lastRefresh = 0;
554	
555	void setup() {
556	  Serial.begin(115200);
557	  Serial1.begin(9600, SERIAL_8N1, -1, PIN_JQ_TX);
558	  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
559	  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
