564	  tft.setBrightness(255);
565	  tft.fillScreen(C_BLACK);
566	  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
567	  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
568	
569	  delay(600);
570	  jqVolume(JQ_VOLUME);
571	  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
572	  delay(900);
573	
574	  loadFallbackQuotes();
575	  if (strlen(WIFI_SSID) > 0) {
576	    splash("Connecting Wi-Fi...", WIFI_SSID);
577	    WiFi.mode(WIFI_STA);
578	    WiFi.setTxPower(WIFI_POWER_8_5dBm);
579	    WiFi.begin(WIFI_SSID, WIFI_PASS);
580	    uint32_t t0 = millis();
581	    while (WiFi.status() != WL_CONNECTED && millis() - t0 < 15000) delay(200);
582	    if (WiFi.status() == WL_CONNECTED) {
583	      Serial.printf("[wifi] %s\n", WiFi.localIP().toString().c_str());
584	      splash("Syncing prescripts...", "");
585	      if (!fetchQuotes()) { splash("Sync failed", "using offline cache"); delay(1200); }
586	    } else {
587	      splash("Wi-Fi unavailable", "using offline cache");
588	      delay(1200);
589	    }
590	  } else {
591	    Serial.println("[wifi] no SSID configured -> offline cache");
592	  }
593	  lastRefresh = millis();
594	  int start = 0;
595	  for (size_t i = 0; i < quotes.size(); i++) if (quotes[i].idx == "6") start = i;
596	  loadQuote(start, true, true);
597	}
598	
599	void loop() {
600	  if (animating) stepAnimation();
601	  if (btnRoll.pressed()) { Serial.println("[btn] ROLL"); rollQuote(); }
602	  if (btnScroll.pressed()) { Serial.println("[btn] SCROLL"); changePage(); }
603	
604	  if (!animating && autoPageAt && millis() >= autoPageAt) {
605	    if (curPage + 1 < (int)pages.size()) { curPage++; showPage(false, true); }
606	    else loadQuote((curQuote + 1) % quotes.size(), true, true);
607	  }
608	  // refresh quote list every 30 min while idle
609	  if (!animating && WiFi.status() == WL_CONNECTED && millis() - lastRefresh > 30UL * 60 * 1000) {
610	    lastRefresh = millis();
611	    std::vector<Quote> keep = quotes;
612	    if (!fetchQuotes()) quotes = keep;
613	    if (curQuote >= (int)quotes.size()) curQuote = 0;
614	  }
