// Rien-Prescript-Beeper // Model 01-Oracle  (ESP32-C3 Supermini + ST7789 170x320 + JQ8900)
#include <Arduino.h>
#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <vector>
#include <string>
#include <math.h>

#include "pins.h"
#include "secrets.h"
#include "lgfx_config.h"
#include "fonts_data.h"
#include "vfont.h"

int g_missingGlyphs = 0;

// ------------------------------------------------------------------ layout
static const int SW = 320, SH = 170;
static const int HDR_H = 21, FTR_H = 23;
static const int BODY_Y = HDR_H, BODY_H = SH - HDR_H - FTR_H;
static const int MAX_CHARS = 36;
static const int MAX_LINES = 4;
static const int LINE_PITCH = 21;
static const uint32_t ENTROPY_MS = 45;
static const uint32_t DRAW_TO_COMPLETE_MS = 1250;
static const uint32_t BETWEEN_COMPLETES_MS = 150;
static const uint32_t DWELL_PER_LINE_MS = 7000;

static const uint16_t C_BLACK = 0x0000, C_WHITE = 0xFFFF;
static const uint16_t C_GHOST = rgb565(0x88, 0x88, 0x88), C_TITLE = rgb565(0x77, 0x77, 0x77);
static const uint16_t C_DIM = rgb565(0x55, 0x55, 0x55), C_SEP = rgb565(0x44, 0x44, 0x44);
static const uint16_t C_RULE = rgb565(0x1e, 0x1e, 0x1e);
static const uint16_t C_BOXBG = rgb565(0x0a, 0x0a, 0x0a);
static const uint16_t ACCENTS[4] = {rgb565(0x38, 0xbd, 0xf8), rgb565(0xf5, 0x9e, 0x0b),
                                    rgb565(0x10, 0xb9, 0x81), rgb565(0xf4, 0x3f, 0x5e)};

static LGFX tft;
static VFont fIT13, fBD13, fRG11, fRG10, fSB10, fSB9;
static uint16_t lineBuf[SW * 24];
static Canvas cv = {lineBuf, SW, 24};

// ------------------------------------------------------------------ data
struct Quote {
  String idx, content, context, date, specific, container, cat;
  std::vector<String> tags;
};
static std::vector<Quote> quotes;
static int curQuote = 0;

static void addFallback(const char* idx, const char* content, const char* ctx, const char* date,
                        const char* specific, const char* container, const char* cat,
                        std::initializer_list<const char*> tags) {
  Quote q;
  q.idx = idx; q.content = content; q.context = ctx; q.date = date;
  q.specific = specific; q.container = container; q.cat = cat;
  for (auto t : tags) q.tags.push_back(t);
  quotes.push_back(q);
}

static void loadFallbackQuotes() {
  quotes.clear();
  addFallback("6",
    "Nỗi sợ lớn nhất của một người đàn ông chính là nước mắt đàn bà. Bản năng của phái mạnh là bao bọc, che chở chứ không phải giẫm đạp, hủy hoại. Bởi thế, đàn ông luôn tránh nói lời chia tay vì không dám đối diện với nước mắt, sợ làm tổn thương người phụ nữ của anh ta. Cũng vì lẽ đó mà trong Series Friends, anh chàng Chandler đã phải năm lần bảy lượt tìm không gian, thời điểm thích hợp nhưng vẫn không thể nói lời tạm biệt với người tình Janice. Vậy tại sao người phụ nữ - vốn được coi là phái yếu lại có thể mạnh mẽ cắt đứt một cuộc tình vốn đã chết trong trái tim đối phương? Vì họ sợ cảm giác bị thương hại. Vì trong tình thế này, nếu cứ cố chấp tiếp tục, tất cả những thương yêu mà đàn bà trao đi chỉ có thể đổi lấy lòng thương hại của người bạn tình hảo tâm, nhân đạo, ưa làm việc thiện nguyện. Nhưng đằng sau quyết định chia ly tưởng chừng dứt khoát luôn là lời cầu khẩn thầm thì ‘Anh ơi anh ở lại’.",
    "Backdrop: Suy ngẫm về sự yếu lòng, bản năng che chở của đàn ông và nỗi sợ bị thương hại của đàn bà trong tình yêu.",
    "2021~2023", "Đàn ông thích mèo, đàn bà yêu chó", "Spiderum - Linh Vũ", "writing",
    {"#Heartbroken", "#Love", "#Wisdom", "#Psychology"});
  addFallback("1", "Static, hum, tum, needle drops,\nSpinning, echo, time just stops.",
    "Vinyl Angel acoustic fiction. A tactile couplet evoking ambient tape hiss.", "2025-07",
    "Vinyl Angel", "Koi no Koe", "music", {"#Music", "#Acoustic", "#VinylAngel"});
  addFallback("2", "Familiar chords fill up the room,\nWrapped inside this faded tomb.",
    "Second couplet of Vinyl Angel narrative suite.", "2025-07",
    "Vinyl Angel", "Koi no Koe", "music", {"#Music", "#Memory", "#Nostalgia"});
}

static String jstr(JsonVariantConst o, const char* a, const char* b = nullptr) {
  JsonVariantConst v = o[a];
  if (v.isNull() && b) v = o[b];
  if (v.isNull()) return "";
  return v.as<String>();
}

static bool fetchQuotes() {
  WiFiClientSecure cli;
  cli.setInsecure();
  HTTPClient http;
  http.setTimeout(12000);
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  if (!http.begin(cli, API_URL)) return false;
  int code = http.GET();
  if (code != 200) {
    Serial.printf("[api] HTTP %d\n", code);
    http.end();
    return false;
  }
  String body = http.getString();
  http.end();
  JsonDocument doc;
  if (deserializeJson(doc, body)) return false;
  std::vector<Quote> fresh;
  auto parseOne = [&](JsonVariantConst o) {
    Quote q;
    q.idx = jstr(o, "idx");
    q.content = jstr(o, "content", "main_content");
    if (q.content.length() == 0) return;
    q.context = jstr(o, "context");
    q.date = jstr(o, "date", "effectiveDate");
    q.specific = jstr(o, "specific", "specificName");
    q.container = jstr(o, "container", "containerName");
    q.cat = jstr(o, "cat", "category");
    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
    for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
      String s = t.as<String>();
      if (!s.startsWith("#")) s = "#" + s;
      q.tags.push_back(s);
    }
    fresh.push_back(q);
  };
  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
  else parseOne(doc.as<JsonVariantConst>());
  if (fresh.empty()) return false;
  quotes = fresh;
  Serial.printf("[api] loaded %d quotes\n", (int)quotes.size());
  return true;
}

// ------------------------------------------------------------------ utf-8
static std::u16string u8to16(const String& s) {
  std::u16string o;
  const uint8_t* p = (const uint8_t*)s.c_str();
  size_t n = s.length();
  for (size_t i = 0; i < n;) {
    uint8_t c = p[i];
    uint32_t cp;
    int len;
    if (c < 0x80) { cp = c; len = 1; }
    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
    else { i++; continue; }
    if (i + len > n) break;
    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
    i += len;
    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
  }
  return o;
}

// ------------------------------------------------------------------ paging (port of buildPrescriptPages)
struct Line { std::u16string t; bool just; };
struct Page { std::vector<Line> lines; bool ctx; };

static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }

static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
  std::u16string w;
  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
  for (char16_t c : s) {
    if (c == '\n') { flush(); tok.push_back(u"\n"); }
    else if (isWS(c)) flush();
    else w.push_back(c);
  }
  flush();
}

static std::u16string trim16(const std::u16string& s) {
  size_t a = 0, b = s.size();
  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
  return s.substr(a, b - a);
}

static bool isWriting(const String& cat) {
  String c = cat; c.trim(); c.toLowerCase();
  return c == "writing" || c == "bài viết" || c == "baiviet";
}

static std::vector<Page> buildPages(const Quote& q) {
  std::vector<Page> pages;
  std::u16string content = trim16(u8to16(q.content));
  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
  std::vector<std::u16string> tok;
  tokenize(content, tok);
  bool writing = isWriting(q.cat);
  size_t ti = 0;
  int pageNum = 0;
  while (ti < tok.size()) {
    pageNum++;
    bool first = pageNum == 1;
    std::vector<std::u16string> pl;
    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
      int budget = MAX_CHARS;
      if (first && ln == 1) budget = MAX_CHARS - 1;
      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
      std::u16string cur;
      while (ti < tok.size()) {
        const std::u16string& nt = tok[ti];
        if (nt == u"\n") { ti++; break; }
        if (cur.empty()) { cur = nt; ti++; }
        else if ((int)(cur.size() + 1 + nt.size()) <= budget) { cur += u" "; cur += nt; ti++; }
        else break;
      }
      pl.push_back(cur);
    }
    size_t la = ti;
    while (la < tok.size() && tok[la] == u"\n") la++;
    bool more = la < tok.size();
    if (first && !pl.empty()) pl[0] = u"\u201C" + pl[0];
    if (more) pl.back() += u"...";
    else pl.back() += u"\u201D";
    Page pg; pg.ctx = false;
    for (size_t i = 0; i < pl.size(); i++) {
      bool terminal = !more && i == pl.size() - 1;
      bool just = writing && !terminal && pl[i].find(u' ') != std::u16string::npos;
      if (!trim16(pl[i]).empty()) pg.lines.push_back({pl[i], just});
    }
    pages.push_back(pg);
  }
  // context pages
  if (q.context.length() > 0) {
    std::vector<std::u16string> cw;
    tokenize(u8to16(q.context), cw);
    size_t ci = 0;
    bool firstCtx = true;
    while (ci < cw.size()) {
      std::vector<std::u16string> cl;
      for (int l = 1; l <= MAX_LINES && ci < cw.size(); l++) {
        int budget = (l == MAX_LINES) ? MAX_CHARS - 4 : MAX_CHARS;
        std::u16string cur;
        if (firstCtx && l == 1) { cur = u"[Note] "; firstCtx = false; }
        while (ci < cw.size()) {
          if (cw[ci] == u"\n") { ci++; continue; }
          if (cur.empty()) { cur = cw[ci]; ci++; }
          else if ((int)(cur.size() + 1 + cw[ci].size()) <= budget || cur == u"[Note] ") {
            if (cur != u"[Note] ") cur += u" ";
            cur += cw[ci]; ci++;
          } else break;
        }
        cl.push_back(cur);
      }
      if (ci < cw.size() && !cl.empty()) cl.back() += u"...";
      Page pg; pg.ctx = true;
      for (auto& s : cl) pg.lines.push_back({s, false});
      pages.push_back(pg);
    }
  }
  return pages;
}

// ------------------------------------------------------------------ JQ8900
static void jqSend(const uint8_t* d, size_t n) {
  uint8_t sum = 0;
  for (size_t i = 0; i < n; i++) sum += d[i];
  Serial1.write(d, n);
  Serial1.write(sum);
}
static void jqPlay(uint8_t track) {
  const uint8_t f[] = {0xAA, 0x07, 0x02, 0x00, track};
  jqSend(f, sizeof f);
}
static void jqVolume(uint8_t v) {
  const uint8_t f[] = {0xAA, 0x13, 0x01, v};
  jqSend(f, sizeof f);
}

// ------------------------------------------------------------------ drawing helpers
static uint16_t hsl565(float h, float s, float l) {
  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
  float c = (1 - fabsf(2 * l - 1)) * s;
  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
  float m = l - c / 2, r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; }
  else if (h < 120) { r = x; g = c; }
  else if (h < 180) { g = c; b = x; }
  else if (h < 240) { g = x; b = c; }
  else if (h < 300) { r = x; b = c; }
  else { r = c; b = x; }
  return rgb565((r + m) * 255, (g + m) * 255, (b + m) * 255);
}

static float tagHue(const String& tag, int idx) {
  int32_t hash = 0;
  for (size_t i = 0; i < tag.length(); i++)
    hash = (int32_t)((((uint32_t)hash << 5) - (uint32_t)hash) + (uint8_t)tag[i]);
  return fabsf(floorf(fmodf((float)((double)hash * 137.508 + idx * 89), 360.f)));
}

static uint16_t accentFor(const Quote& q) {
  int n = q.idx.toInt();
  if (n < 0) n = -n;
  return ACCENTS[n % 4];
}

static void push(int y, int h) {
  tft.startWrite();
  tft.pushImage(0, y, SW, h, lineBuf);
  tft.endWrite();
}

static void drawHeader(const Quote& q, bool busy) {
  cv.h = HDR_H;
  cv.fill(C_BLACK);
  cv.rect(0, HDR_H - 1, SW, 1, C_RULE);
  const int base = 14;
  std::u16string date = u8to16(q.date.length() ? q.date : String("—"));
  int dateW = fSB10.adv * (int)date.size();
  int labelW = fRG10.adv * 5;
  int rightW = labelW + 4 + dateW;
  int rx = SW - 12 - rightW;
  cv.text(fRG10, rx, base, u"Date:", C_DIM);
  cv.text(fSB10, rx + labelW + 4, base, date, C_GHOST);
  int x = 12;
  if (busy) {
    cv.text(fRG10, x, base, u"// Receiving prescript...", C_GHOST);
  } else {
    std::u16string idx = u"#" + u8to16(q.idx);
    x += cv.text(fSB10, x, base, idx, C_GHOST) + 4;
    x += cv.text(fRG10, x, base, u"~", C_SEP) + 4;
    std::u16string title = u8to16(q.specific);
    int avail = rx - 8 - x;
    int maxCh = avail / fRG10.adv;
    if ((int)title.size() > maxCh && maxCh > 1) title = title.substr(0, maxCh - 1) + u"\u2026";
    cv.text(fRG10, x, base, title, C_TITLE, avail);
  }
  push(0, HDR_H);
}

static void drawFooter(const Quote& q, int seed = 0) {
  cv.h = FTR_H;
  cv.fill(C_BLACK);
  cv.rect(0, 0, SW, 1, C_RULE);
  uint16_t accent = accentFor(q);
  const int base = 15;
  std::u16string cont = u8to16(q.container);
  int contMax = 150 / fSB10.adv;
  if ((int)cont.size() > contMax) cont = cont.substr(0, contMax - 1) + u"\u2026";
  int contW = fSB10.adv * (int)cont.size();
  int cx = SW - 12 - contW;
  cv.text(fSB10, cx, base, cont, accent);
  int x = 12;
  for (size_t i = 0; i < q.tags.size(); i++) {
    std::u16string t = u8to16(q.tags[i]);
    int w = fSB9.adv * (int)t.size() + 10 + 2;
    if (x + w > cx - 8) break;
    float hue = tagHue(q.tags[i], (int)i) + seed;
    uint16_t tcol = hsl565(hue, 0.85f, 0.72f), bg = hsl565(hue, 0.65f, 0.08f);
    uint16_t bd = mix565(C_BLACK, hsl565(hue, 0.70f, 0.40f), 115);
    const int y0 = 5, hh = 13;
    cv.rect(x, y0, w, hh, bd);
    cv.rect(x + 1, y0 + 1, w - 2, hh - 2, bg);
    cv.b[y0 * cv.w + x] = C_BLACK; cv.b[y0 * cv.w + x + w - 1] = C_BLACK;
    cv.b[(y0 + hh - 1) * cv.w + x] = C_BLACK; cv.b[(y0 + hh - 1) * cv.w + x + w - 1] = C_BLACK;
    cv.text(fSB9, x + 6, y0 + 10, t, tcol);
    x += w + 3;
  }
  push(SH - FTR_H, FTR_H);
}

// ------------------------------------------------------------------ page rendering
static int bodyTop(int n) {
  int blockH = n * LINE_PITCH - 2;
  int y = BODY_Y + (BODY_H - blockH) / 2;
  return y < BODY_Y ? BODY_Y : y;
}

static void clearBody() {
  tft.startWrite();
  tft.fillRect(0, BODY_Y, SW, BODY_H, C_BLACK);
  tft.endWrite();
}

static void drawBodyLineFinal(const Line& ln, int y, bool ctx, uint16_t accent) {
  cv.h = 20;
  cv.fill(ctx ? C_BOXBG : C_BLACK);
  const VFont& fn = ctx ? fRG11 : fIT13;
  int base = (20 - (fn.ascent + fn.descent)) / 2 + fn.ascent;
  int cellW = fn.adv;
  int x0 = ctx ? 16 : 16;
  if (ctx) cv.rect(10, 0, 2, 20, C_DIM);
  const std::u16string& s = ln.t;
  std::vector<int> xs(s.size());
  int spaces = 0;
  for (char16_t c : s) if (c == ' ') spaces++;
  if (ln.just && spaces > 0) {
    int W = MAX_CHARS * cellW;
    int gap = W - (int)(s.size() - spaces) * cellW;
    int extra = gap - spaces * 0;
    int per = extra / spaces, rem = extra % spaces, x = x0, sp = 0;
    for (size_t i = 0; i < s.size(); i++) {
      xs[i] = x;
      if (s[i] == ' ') x += per + (sp++ < rem ? 1 : 0);
      else x += cellW;
    }
  } else {
    for (size_t i = 0; i < s.size(); i++) xs[i] = x0 + (int)i * cellW;
  }
  for (size_t i = 0; i < s.size(); i++) {
    char16_t c = s[i];
    if (c == ' ') continue;
    if (!ctx && (c == 0x201C || c == 0x201D || c == '.')) cv.drawChar(fBD13, xs[i], base, c, accent);
    else cv.drawChar(fn, xs[i], base, c, ctx ? C_GHOST : C_WHITE);
  }
  push(y, 20);
}

static void renderPageFinal(const Page& pg, uint16_t accent) {
  clearBody();
  int y = bodyTop((int)pg.lines.size());
  for (size_t i = 0; i < pg.lines.size(); i++) drawBodyLineFinal(pg.lines[i], y + (int)i * LINE_PITCH, pg.ctx, accent);
}

// ------------------------------------------------------------------ entropy animation
struct Cell { char16_t target, cur; uint32_t life, nextScr; bool locked; };
static Cell grid[MAX_LINES][MAX_CHARS + 8];
static int gridLen[MAX_LINES];
static const char SCRAMBLE[] = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789!$*+=-~?/";
static char16_t rndCipher() { return SCRAMBLE[random(sizeof(SCRAMBLE) - 1)]; }

// ------------------------------------------------------------------ state
static std::vector<Page> pages;
static int curPage = 0;
static bool animating = false;
static uint32_t animStart = 0, lastFrame = 0, nextChime = 0, autoPageAt = 0;
static uint16_t curAccent = ACCENTS[0];

static void scheduleAutoPage() {
  int lines = (int)pages[curPage].lines.size();
  if (lines < 1) lines = 1;
  autoPageAt = millis() + lines * DWELL_PER_LINE_MS;
}

static void finishAnimation(bool playChime) {
  animating = false;
  renderPageFinal(pages[curPage], curAccent);
  drawHeader(quotes[curQuote], false);
  if (playChime) jqPlay(TRACK_COMPLETE);
  scheduleAutoPage();
}

static void showPage(bool animate, bool sound) {
  const Quote& q = quotes[curQuote];
  curAccent = accentFor(q);
  autoPageAt = 0;
  Page& pg = pages[curPage];
  drawFooter(q);
  if (!animate || pg.ctx) {
    animating = false;
    drawHeader(q, false);
    renderPageFinal(pg, curAccent);
    if (sound) jqPlay(TRACK_COMPLETE);
    scheduleAutoPage();
    return;
  }
  drawHeader(q, true);
  clearBody();
  uint32_t total = max<uint32_t>(900, ENTROPY_MS * 35);
  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
    const std::u16string& s = pg.lines[r].t;
    gridLen[r] = min<int>((int)s.size(), MAX_CHARS + 8);
    for (int c = 0; c < gridLen[r]; c++)
      grid[r][c] = {s[c], rndCipher(), (uint32_t)random(total), (uint32_t)random(40), false};
  }
  animating = true;
  animStart = millis();
  lastFrame = 0;
  if (sound) { jqPlay(TRACK_DRAW); nextChime = animStart + DRAW_TO_COMPLETE_MS; }
  else nextChime = 0xFFFFFFFF;
}

static void loadQuote(int idx, bool animate, bool sound) {
  curQuote = idx;
  pages = buildPages(quotes[curQuote]);
  curPage = 0;
  g_missingGlyphs = 0;
  showPage(animate, sound);
  Serial.printf("[quote] #%s pages=%d missingGlyphs=%d heap=%u\n", quotes[curQuote].idx.c_str(),
                (int)pages.size(), g_missingGlyphs, ESP.getFreeHeap());
}

static void rollQuote() {
  int n = (int)quotes.size(), i = curQuote;
  if (n > 1) while (i == curQuote) i = random(n);
  loadQuote(i, true, true);
}

static void changePage() {
  if (animating) { finishAnimation(true); return; }
  curPage = (curPage + 1) % (int)pages.size();
  showPage(false, true);
}

static void stepAnimation() {
  uint32_t now = millis();
  if (now >= nextChime) { jqPlay(TRACK_COMPLETE); nextChime = now + BETWEEN_COMPLETES_MS; }
  if (now - lastFrame < 33) return;
  lastFrame = now;
  uint32_t el = now - animStart;
  Page& pg = pages[curPage];
  bool all = true;
  int y = bodyTop((int)pg.lines.size());
  const int base = (20 - (fIT13.ascent + fIT13.descent)) / 2 + fIT13.ascent;
  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
    cv.h = 20;
    cv.fill(C_BLACK);
    for (int c = 0; c < gridLen[r]; c++) {
      Cell& ce = grid[r][c];
      if (!ce.locked) {
        if (el >= ce.life) { ce.locked = true; ce.cur = ce.target; }
        else {
          all = false;
          if (el >= ce.nextScr) { ce.cur = rndCipher(); ce.nextScr = el + 35 + random(25); }
        }
      }
      int x = 16 + c * fIT13.adv;
      if (ce.locked) {
        if (ce.target == ' ') continue;
        if (ce.target == 0x201C || ce.target == 0x201D || ce.target == '.')
          cv.drawChar(fBD13, x, base, ce.target, curAccent);
        else cv.drawChar(fIT13, x, base, ce.target, C_WHITE);
      } else cv.drawChar(fIT13, x, base, ce.cur, C_WHITE);
    }
    push(y + r * LINE_PITCH, 20);
  }
  if (all) finishAnimation(true);
}

// ------------------------------------------------------------------ boot UI
static void splash(const char* l1, const char* l2 = "") {
  cv.h = 24;
  tft.fillRect(0, 60, SW, 60, C_BLACK);
  std::u16string a = u8to16(l1), b = u8to16(l2);
  cv.fill(C_BLACK);
  cv.text(fSB10, (SW - (int)a.size() * fSB10.adv) / 2, 16, a, C_WHITE);
  push(66, 24);
  cv.fill(C_BLACK);
  cv.text(fRG10, (SW - (int)b.size() * fRG10.adv) / 2, 16, b, C_GHOST);
  push(92, 24);
}

struct Btn {
  uint8_t pin; bool last = true; uint32_t t = 0;
  bool pressed() {
    bool v = digitalRead(pin);
    uint32_t now = millis();
    bool fire = (last && !v && now - t > 40);
    if (v != last) t = now;
    last = v;
    return fire;
  }
};
static Btn btnRoll = {PIN_BTN_ROLL}, btnScroll = {PIN_BTN_SCROLL};
static uint32_t lastRefresh = 0;

void setup() {
  Serial.begin(115200);
  Serial1.begin(9600, SERIAL_8N1, -1, PIN_JQ_TX);
  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
  randomSeed(esp_random());

  tft.init();
  tft.setRotation(1);
  tft.setBrightness(255);
  tft.fillScreen(C_BLACK);
  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);

  delay(600);
  jqVolume(JQ_VOLUME);
  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
  delay(900);

  loadFallbackQuotes();
  if (strlen(WIFI_SSID) > 0) {
    splash("Connecting Wi-Fi...", WIFI_SSID);
    WiFi.mode(WIFI_STA);
    WiFi.setTxPower(WIFI_POWER_8_5dBm);
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    uint32_t t0 = millis();
    while (WiFi.status() != WL_CONNECTED && millis() - t0 < 15000) delay(200);
    if (WiFi.status() == WL_CONNECTED) {
      Serial.printf("[wifi] %s\n", WiFi.localIP().toString().c_str());
      splash("Syncing prescripts...", "");
      if (!fetchQuotes()) { splash("Sync failed", "using offline cache"); delay(1200); }
    } else {
      splash("Wi-Fi unavailable", "using offline cache");
      delay(1200);
    }
  } else {
    Serial.println("[wifi] no SSID configured -> offline cache");
  }
  lastRefresh = millis();
  int start = 0;
  for (size_t i = 0; i < quotes.size(); i++) if (quotes[i].idx == "6") start = i;
  loadQuote(start, true, true);
}

void loop() {
  if (animating) stepAnimation();
  if (btnRoll.pressed()) { Serial.println("[btn] ROLL"); rollQuote(); }
  if (btnScroll.pressed()) { Serial.println("[btn] SCROLL"); changePage(); }

  if (!animating && autoPageAt && millis() >= autoPageAt) {
    if (curPage + 1 < (int)pages.size()) { curPage++; showPage(false, true); }
    else loadQuote((curQuote + 1) % quotes.size(), true, true);
  }
  // refresh quote list every 30 min while idle
  if (!animating && WiFi.status() == WL_CONNECTED && millis() - lastRefresh > 30UL * 60 * 1000) {
    lastRefresh = millis();
    std::vector<Quote> keep = quotes;
    if (!fetchQuotes()) quotes = keep;
    if (curQuote >= (int)quotes.size()) curQuote = 0;
  }
  delay(1);
}

