1371	      if (prevBtn) prevBtn.style.opacity = (currentPage <= 1) ? '0.4' : '1';
1372	      if (nextBtn) nextBtn.style.opacity = (currentPage >= totalPages) ? '0.4' : '1';
1373	    }
1374	
1375	    function changePage(direction) {
1376	      if (autoPageTimer) { clearTimeout(autoPageTimer); autoPageTimer = null; }
1377	      const target = currentPage + direction;
1378	      if (target >= 1 && target <= totalPages) {
1379	        currentPage = target;
1380	        playSoundEffect('complete');
1381	        renderActivePrescript(false);
1382	      }
1383	    }
1384	
1385	    function goToPage(pageNum) {
1386	      if (autoPageTimer) { clearTimeout(autoPageTimer); autoPageTimer = null; }
1387	      if (pageNum === 999) pageNum = totalPages;
1388	      if (pageNum >= 1 && pageNum <= totalPages) {
1389	        currentPage = pageNum;
1390	        playSoundEffect('complete');
1391	        renderActivePrescript(false);
1392	      }
1393	    }
1394	
1395	    // ==============================================================================
1396	    // 6. METADATA NORMALIZATION & COLOR GENERATOR
1397	    // ==============================================================================
1398	    function generateTagColorStyle(tagName, tagIndex) {
1399	      let hash = 0;
1400	      for (let i = 0; i < tagName.length; i++) {
1401	        hash = ((hash << 5) - hash) + tagName.charCodeAt(i);
1402	        hash |= 0;
1403	      }
1404	      const goldenAngle = 137.508;
1405	      const hue = Math.abs(Math.floor((hash * goldenAngle + tagIndex * 89 + reRollSeed) % 360));
1406	
1407	      const textColor   = `hsl(${hue}, 85%, 72%)`;
1408	      const borderColor = `hsla(${hue}, 70%, 40%, 0.45)`;
1409	      const bgColor     = `hsla(${hue}, 65%, 8%, 0.9)`;
1410	      return `background: ${bgColor} !important; border-color: ${borderColor} !important; color: ${textColor} !important;`;
1411	    }
1412	
1413	    function resolveBundle(q) {
1414	      if (!q) return null;
1415	
1416	      const content = q.main_content || "";
1417	      const context = q.context || "";
1418	      const specific = availableSpecifics.find(s => s.id === q.specific_id);
1419	      const specificName = q.specificName || (specific ? specific.name : "—");
1420	      const containerName = q.containerName || (specific && specific.container ? specific.container.name : (specific ? (specific.container_name || "—") : "—"));
1421	
1422	      let effectiveDate = (q.date || q.effectiveDate || "").trim();
1423	      if (!effectiveDate && specific && specific.date) {
1424	        effectiveDate = specific.date.trim();
1425	      }
1426	
1427	      let hashtagThemes = q.hashtagThemes || [];
1428	      if (hashtagThemes.length === 0 && q.theme_ids) {
1429	        hashtagThemes = (q.theme_ids || []).map(tid => {
1430	          const th = availableThemes.find(t => t.id === tid);
1431	          return th ? `#${th.name}` : `#${tid}`;
1432	        });
1433	      }
1434	      if (hashtagThemes.length === 0) hashtagThemes = ["#Wisdom"];
1435	
1436	      const rawCategory = q.category || (specific ? specific.category : "") || "";
1437	
1438	      return {
1439	        idx: q.idx ?? q.index ?? 1,
1440	        content,
1441	        context,
1442	        category: rawCategory,
1443	        specificName,
1444	        containerName,
1445	        effectiveDate: effectiveDate || "—",
1446	        hashtagThemes
1447	      };
1448	    }
