1509	                if (ch === '.') return `<span class="ep-c ep-ellipsis-cue" style="color:${sharedAccentColor};">.</span>`;
1510	                if (ch === ' ') return `<span class="ep-c ep-space"> </span>`;
1511	                return `<span class="ep-c">${ch}</span>`;
1512	              }).join('');
1513	              return `<div class="ep-text-line ${line.align || 'line-left'}">${formattedHtml}</div>`;
1514	            }).join('')}
1515	          </div>
1516	        `;
1517	      }
1518	
1519	      // Header Components (Clean single-line with ellipsis on long titles)
1520	      const headerTitleHTML = `<span class="ep-header-left" id="ep-header-left-title"><strong class="ep-idx-num">#${b.idx}</strong><span class="ep-sep">~</span><span class="ep-specific-title">${b.specificName}</span></span>`;
1521	      lastFinalHeaderTitleHTML = `<strong class="ep-idx-num">#${b.idx}</strong><span class="ep-sep">~</span><span class="ep-specific-title">${b.specificName}</span>`;
1522	      const headerDateHTML = `<span class="ep-header-right"><span style="color:#555;">Date:</span><span class="ep-date-val">${b.effectiveDate}</span></span>`;
1523	
1524	      // Tags Blocks
1525	      const tagsBlocks = b.hashtagThemes.map((t, idx) => {
1526	        const tagStyle = generateTagColorStyle(t, idx);
1527	        return `<span class="ep-tag-block" style="${tagStyle}">${t}</span>`;
1528	      }).join('');
1529	
1530	      // Container Name (Clean origin without page counters)
1531	      const containerHTML = `<span class="ep-container-name" style="color:${sharedAccentColor};">${b.containerName}</span>`;
1532	
1533	      lastRenderedPageData = activePage;
1534	      lastRenderedAlignClass = alignClass;
1535	
1536	      // Render Screen with EXACT 4-LINE BODY (ZERO EXTRA BANNERS // ZERO SCROLLBAR)
1537	      screen.innerHTML = `
