1546	          ${contentHTML}
1547	        </div>
1548	
1549	        <!-- ZONE 4: FIXED HARDWARE FOOTER -->
1550	        <div class="ep-footer">
1551	          <div class="ep-tags">${tagsBlocks}</div>
1552	          <div class="ep-attribution">${containerHTML}</div>
1553	        </div>
1554	      `;
1555	
1556	      if (shouldAnimate && animationEnabled && activePage.type === 'quote') {
1557	        runPrescriptTypewriter(activePage, alignClass);
1558	      } else {
1559	        stopDrawingAnimation();
1560	        resetAutoPageTimer(activePage);
1561	      }
1562	
1563	      // Attach debounced wheel listener for discrete page flipping
1564	      const vp = document.getElementById('ep-viewport');
1565	      if (vp) {
1566	        vp.onwheel = (e) => {
1567	          e.preventDefault();
1568	          if (wheelDebounceTimer) return;
1569	          wheelDebounceTimer = setTimeout(() => { wheelDebounceTimer = null; }, 180);
1570	          if (e.deltaY > 15) changePage(1);
