267	// ------------------------------------------------------------------ drawing helpers
268	static uint16_t hsl565(float h, float s, float l) {
269	  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
270	  float c = (1 - fabsf(2 * l - 1)) * s;
271	  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
272	  float m = l - c / 2, r = 0, g = 0, b = 0;
273	  if (h < 60) { r = c; g = x; }
274	  else if (h < 120) { r = x; g = c; }
275	  else if (h < 180) { g = c; b = x; }
276	  else if (h < 240) { g = x; b = c; }
277	  else if (h < 300) { r = x; b = c; }
278	  else { r = c; b = x; }
279	  return rgb565((r + m) * 255, (g + m) * 255, (b + m) * 255);
280	}
