283	  int32_t hash = 0;
284	  for (size_t i = 0; i < tag.length(); i++)
285	    hash = (int32_t)((((uint32_t)hash << 5) - (uint32_t)hash) + (uint8_t)tag[i]);
286	  return fabsf(floorf(fmodf((float)((double)hash * 137.508 + idx * 89), 360.f)));
287	}
