void setup() {
  Serial.begin(115200);
  Serial1.begin(9600, SERIAL_8N1, -1, PIN_JQ_TX);
  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
  randomSeed(esp_random());

  Serial.println("\n=== ESP32 Rien-Prescript-Beeper Boot ===");
  Serial.printf("Free heap: %u bytes\n", ESP.getFreeHeap());

  Serial.println("Initializing TFT display...");
  tft.init();
  Serial.println("TFT initialized");

  tft.setRotation(1);
  Serial.println("TFT rotation set to 1 (landscape)");

  tft.setBrightness(255);
  Serial.println("TFT brightness set to maximum");

  tft.fillScreen(C_WHITE);  // Test with white first
  Serial.println("TFT filled with white - display should show white screen");
  delay(2000);

  tft.fillScreen(C_BLACK);
  Serial.println("TFT filled with black");

  // Test basic drawing
  tft.fillRect(50, 50, 100, 50, rgb565(255, 0, 0)); // Red rectangle
  Serial.println("Drew red test rectangle");
  delay(1000);

  tft.fillScreen(C_BLACK);
  Serial.println("Display test complete, initializing fonts...");

  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
  Serial.println("Fonts initialized");

  delay(600);
  Serial.println("Setting JQ8900 volume...");
  jqVolume(JQ_VOLUME);
  Serial.printf("JQ8900 volume set to %d\n", JQ_VOLUME);

  Serial.println("Showing splash screen...");
  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
  delay(900);
}

