5	// Minimal reader + software renderer for the VLW-layout fonts from tools/make_fonts.py
6	struct Glyph {
7	  int w, h, adv, dY, dX;
8	  const uint8_t* bits;
9	};
10	
11	struct VFont {
12	  const uint8_t* d = nullptr;
13	  uint32_t n = 0;
14	  int size = 0, ascent = 0, descent = 0, adv = 0;
15	  const uint8_t* recs = nullptr;
16	  const uint8_t* bmp = nullptr;
17	
18	  static int32_t be(const uint8_t* p) {
19	    return (int32_t)(((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]);
20	  }
21	  void init(const uint8_t* data) {
22	    d = data;
23	    n = be(d);
24	    size = be(d + 8);
25	    ascent = be(d + 16);
26	    descent = be(d + 20);
27	    recs = d + 24;
28	    bmp = recs + n * 28;
29	    Glyph g;
30	    adv = find('M', g) ? g.adv : size * 6 / 10;
31	  }
32	  bool find(char16_t cp, Glyph& g) const {
33	    int lo = 0, hi = (int)n - 1;
34	    while (lo <= hi) {
35	      int mid = (lo + hi) >> 1;
36	      const uint8_t* r = recs + mid * 28;
37	      int32_t u = be(r);
38	      if (u == cp) {
39	        g.h = be(r + 4);
40	        g.w = be(r + 8);
41	        g.adv = be(r + 12);
42	        g.dY = be(r + 16);
43	        g.dX = be(r + 20);
44	        g.bits = bmp + be(r + 24);
45	        return true;
46	      } else if (u < cp) lo = mid + 1;
47	      else hi = mid - 1;
48	    }
49	    return false;
50	  }
51	};
