struct Btn {
  uint8_t pin; bool last = true; uint32_t t = 0;
  bool pressed() {
    bool v = digitalRead(pin);
    uint32_t now = millis();
    bool fire = (last && !v && now - t > 250);
    if (v != last) t = now;
    last = v;
    return fire;
  }
};
static Btn btnRoll = {PIN_BTN_ROLL}, btnScroll = {PIN_BTN_SCROLL};
static uint32_t lastRefresh = 0;

void setup() {
  Serial.begin(115200);
  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
  randomSeed(esp_random());

  // Initialize audio driver
  audio.begin(PIN_JQ_TX);
  delay(100);
  audio.setVolume(JQ_VOLUME);

  // Hardware reset pulse on LCD RST pin
  pinMode(PIN_LCD_RST, OUTPUT);
  digitalWrite(PIN_LCD_RST, HIGH);
  delay(50);
  digitalWrite(PIN_LCD_RST, LOW);
  delay(100);
  digitalWrite(PIN_LCD_RST, HIGH);
  delay(150);

  tft.init();
  tft.setRotation(1);
  tft.setBrightness(255);
  tft.fillScreen(C_BLACK);

  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
  Serial.println("Fonts initialized");

  delay(300);

