void loop() {
  if (Serial.available()) {
    char ch = Serial.read();
    if (ch == 'r' || ch == 'R') {
      Serial.println("[SIM] ROLL trigger");
      rollQuote();
      return;
    }
    if (ch == 's' || ch == 'S') {
      Serial.println("[SIM] SCROLL trigger");
      changePage();
      return;
    }
  }

  if (btnRoll.pressed() || btnRollAlt.pressed() || btnBoot.pressed()) {
    Serial.println("[btn] ROLL");
    rollQuote();
    return;
  }
  if (btnScroll.pressed()) {
    Serial.println("[btn] SCROLL");
    changePage();
    return;
  }

  if (animating) {
    stepAnimation();
  }

  if (!animating && autoPageAt && millis() >= autoPageAt) {
    if (curPage + 1 < (int)pages.size()) { curPage++; showPage(false, true); }
    else loadQuote((curQuote + 1) % quotes.size(), true, true);
  }
  // refresh quote list every 30 min while idle
  if (!animating && WiFi.status() == WL_CONNECTED && millis() - lastRefresh > 30UL * 60 * 1000) {
    lastRefresh = millis();
    std::vector<Quote> keep = quotes;
    if (!fetchQuotes()) quotes = keep;
    if (curQuote >= (int)quotes.size()) curQuote = 0;
  }
  delay(1);
}

