static void stepAnimation() {
  uint32_t now = millis();
  uint32_t el = now - animStart;
  if (now >= nextChime) { jqPlay(TRACK_COMPLETE); nextChime = now + BETWEEN_COMPLETES_MS; }
  if (now - lastFrame < 30) return;
  lastFrame = now;
  animFrameCount++;

  bool all = renderAnimationFrame(el);
  if (all || el >= 2000) finishAnimation(true);
}

